import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Last-known prices keep totals available during a price-service DNS outage.  The
# fallback is deliberately limited to known SKUs so an unavailable service does
# not turn an unknown product into an incorrect total.
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    total = 0.0
    for sku in skus:
        try:
            total += get_price(sku)
        except urllib.error.HTTPError:
            raise
        except urllib.error.URLError:
            if sku not in _FALLBACK_PRICES:
                raise
            total += _FALLBACK_PRICES[sku]
    return total
